// Bound in-process `ctx.run*` composition depth so a self- or cyclically-
// referencing call fails loudly with a clear error instead of overflowing the
// stack. Tracked across the awaited handler chain (one DO invocation is
// single-threaded), so the counter reflects true nesting depth.
const MAX_RUN_DEPTH = 32;
let runDepth = 0;

const dispatchRun = async (expected: FunctionKind, functionPath: string, args: Record<string, unknown>, ctx: unknown): Promise<unknown> => {
    const registered = LUNORA_FUNCTIONS[functionPath];

    if (!registered) {
        throw new Error(`unknown function: ${functionPath}`);
    }

    if (registered.kind !== expected) {
        throw new Error(`ctx.run${expected[0]!.toUpperCase()}${expected.slice(1)}: "${functionPath}" is registered as a ${registered.kind}, not a ${expected}`);
    }

    if (runDepth >= MAX_RUN_DEPTH) {
        throw new LunoraError("RUN_DEPTH_EXCEEDED", `ctx.run*: composition depth limit (${MAX_RUN_DEPTH}) exceeded — likely a cyclic runQuery/runMutation`);
    }

    runDepth += 1;

    try {
        return await registered.handler(ctx, args);
    } finally {
        runDepth -= 1;
    }
};

/**
 * Build the project's shard Durable Object. Export the result as `ShardDO`
 * from the worker entry so wrangler binds it by name.
 */
export const createShardDO = (config: ShardDOConfig = {}): new (state: ShardDOState, env: unknown) => ShardDOBase =>
    class extends ShardDOBase {
        private migrated = false;

        public override async handleRpc(functionPath: string, args: Record<string, unknown>, headroom?: TransactionHeadroomTracker): Promise<unknown> {
            const registered = LUNORA_FUNCTIONS[functionPath];

            // Internal functions are reachable server-side only: via `ctx.run*`
            // composition, or a trusted system dispatch (scheduler/cron, marked by
            // `isSystemDispatch()`). A client RPC never carries that flag, so its
            // internals stay not-found and never leak across the external boundary.
            if (!registered || (registered.visibility === "internal" && !this.isSystemDispatch())) {
                throw new LunoraError("FUNCTION_NOT_FOUND", `function not registered: ${functionPath}`);
            }

            this.ensureMigrated();

            // `headroom`, when the caller supplied one, is threaded straight
            // through to `buildCtx` — bypassing its `this.transactionHeadroom()`
            // fallback (the racy shared-field read) entirely for THIS dispatch.
            // The main `/rpc` path always supplies one; `dispatchLifecycle` /
            // `handleRunAs` don't mint their own and omit it, so they keep the
            // prior fallback behavior unchanged.
            const ctx = this.buildCtx({ functionPath, headroom });

            // A mutation's writes must commit all-or-nothing: wrap its dispatch in
            // the DO's BEGIN/COMMIT span so any throw (a validator, an RLS denial,
            // an OCC conflict, a failed row mid-`insertMany`/`patchMany`) rolls
            // back every write the mutation made. Queries are read-only and actions
            // do external I/O that can't be rolled back, so both dispatch directly.
            // `ctx.run*` composition runs inside this span (it never re-enters
            // handleRpc); runInTransaction's own guard rejects accidental nesting.
            //
            // The replay bookkeeping (idempotency dedup row + custom-mutator
            // watermark advance) commits INSIDE this span via
            // `commitMutationBookkeeping`, so the writes, the dedup row, and the
            // watermark are atomic — a crash can't leave the writes durable without
            // the replay guard.
            if (registered.kind === "mutation") {
                return this.runInTransaction(async () => {
                    const result = await registered.handler(ctx, args);

                    this.commitMutationBookkeeping(result);

                    return result;
                });
            }

            return registered.handler(ctx, args);
        }

        protected override async runRelationFanoutRead(functionPath: string, args: Record<string, unknown>): Promise<unknown> {
            this.ensureMigrated();

            const { db } = this.buildCtx({ functionPath }) as { db: DatabaseWriterLike };

            return serveRelationFanout(schema as unknown as SchemaLike, db, functionPath, args);
        }

        protected override async executeSubscription(functionPath: string, args: Record<string, unknown>, identity?: { identity?: Record<string, unknown>; userId?: string }): Promise<{ ranges?: Map<string, KeyRange[]>; result: unknown; tables: Set<string> } | null> {
            const registered = LUNORA_FUNCTIONS[functionPath];

            if (!registered || registered.kind !== "query" || registered.visibility === "internal") {
                return null;
            }

            this.ensureMigrated();

            const footprint = createReadFootprint();
            // Identity is threaded EXPLICITLY from the (deferred/interleaved)
            // subscription caller — never read from the shared per-request field
            // here — so a concurrent RPC can't leak its identity into this re-run.
            const ctx = this.buildCtx({ functionPath, headroom: this.subscriptionHeadroom(), identity, onRead: footprint.onRead, onReadRange: footprint.onReadRange });
            const result = await registered.handler(ctx, args);

            // Ranges come from THIS run's reads, never a shared field on the DO:
            // a deferred re-run interleaves with unrelated dispatches.
            return { ranges: footprint.ranges(), result, tables: footprint.tables };
        }

        protected override executeStream(functionPath: string, args: Record<string, unknown>): null | { iterator: (signal: AbortSignal) => AsyncIterable<unknown> } {
            const registered = LUNORA_FUNCTIONS[functionPath];

            if (!registered || registered.kind !== "stream" || registered.visibility === "internal") {
                return null;
            }

            this.ensureMigrated();

            return {
                iterator: (signal) => (registered.handler as (context: unknown, args: Record<string, unknown>, signal: AbortSignal) => AsyncIterable<unknown>)(this.buildCtx({ functionPath }), args, signal),
            };
        }

        protected override lifecycleHookPaths(event: "connect" | "disconnect"): readonly string[] {
            return LUNORA_LIFECYCLE_HOOKS[event];
        }

        protected override tableRefs(table: string): Record<string, string> | undefined {
            return LUNORA_TABLE_REFS[table];
        }

        protected override tableIndexes(table: string): Array<{ fields: string[]; name: string; type: "geo" | "index" | "rank" | "search" | "vector"; unique?: boolean }> {
            return LUNORA_TABLE_INDEXES[table] ?? [];
        }

        protected override ttlSweeps(): ReadonlyArray<{ after?: number; field: string; softDeleteField?: string; table: string }> {
            return LUNORA_TTL_SWEEPS;
        }

        protected override tableColumns(table: string): Array<{ isStorage?: boolean; name: string; optional: boolean; pk?: boolean; ref?: string; type: string }> {
            return LUNORA_TABLE_COLUMNS[table] ?? [];
        }

        protected override storageColumns(): Record<string, string[]> {
            return LUNORA_STORAGE_COLUMNS;
        }

        protected override rlsMetadata(): RlsPoliciesResult {
            return LUNORA_RLS_METADATA;
        }

        protected override maskMetadata(): MaskPoliciesResult {
            return LUNORA_MASK_METADATA;
        }

        protected override storageRulesMetadata(): StorageRulesResult {
            return LUNORA_STORAGE_RULES;
        }

        protected override studioFeatures(): StudioFeaturesResult {
            return LUNORA_STUDIO_FEATURES;
        }

        protected override advisories(): AdvisoryFinding[] {
            return LUNORA_ADVISORIES;
        }

        protected override advisorProcedures(): AdvisorProcedure[] {
            return LUNORA_ADVISOR_PROCEDURES;
        }

        protected override async runShardDataMigration(args: RunShardMigrationArgs): Promise<MigrationRunResult> {
            const migration = LUNORA_MIGRATIONS[args.id];

            if (!migration) {
                throw new LunoraError("MIGRATION_NOT_FOUND", `data migration "${args.id}" is not registered`, { status: 404 });
            }

            this.ensureMigrated();

            const env = (this.env ?? {}) as Record<string, unknown>;
            const scheduler = (config.scheduler?.(env) ?? schedulerStub) as SchedulerLike;
            const writer = createShardCtxDb({
                broadcast: (delta) => {
                    this.recordChangedTable(delta.table, delta.indexKeys);
                },
                cdc: config.cdc ?? false,
                scheduler,
                schema: schema as unknown as SchemaLike,
                sql: this.sql as SqlExec,
            });

            return runDataMigration({
                batchSize: args.batchSize,
                direction: args.direction,
                dryRun: args.dryRun,
                maxBatches: args.maxBatches,
                migration: migration as unknown as DataMigrationLike,
                // Flush after each batch so live migrationStatus subscribers see
                // progress mid-run (the base method records the reserved state
                // table the raw-SQL progress write is invisible to the tracker).
                onBatch: () => this.flushMigrationProgress(),
                sql: this.sql as SqlExec,
                writer,
            });
        }

        protected override async runShardWrite(args: RunShardWriteArgs): Promise<RunShardWriteResult> {
            const definition = (schema as unknown as SchemaLike).tables[args.table];

            if (!definition) {
                throw new LunoraError("UNKNOWN_TABLE", `unknown table: ${args.table}`, { status: 404 });
            }

            // `.global()` tables live in D1, not this DO's SQLite — editing them
            // here would corrupt nothing but would fail confusingly, so reject up
            // front with a clear code the studio can surface.
            if (definition.shardMode?.kind === "global") {
                throw new LunoraError("GLOBAL_TABLE_NOT_EDITABLE", `table "${args.table}" is global; edit it through D1, not the shard`, { status: 400 });
            }

            this.ensureMigrated();

            const env = (this.env ?? {}) as Record<string, unknown>;
            const scheduler = (config.scheduler?.(env) ?? schedulerStub) as SchedulerLike;
            const writer = createShardCtxDb({
                broadcast: (delta) => {
                    this.recordChangedTable(delta.table, delta.indexKeys);
                },
                cdc: config.cdc ?? false,
                scheduler,
                schema: schema as unknown as SchemaLike,
                sql: this.sql as SqlExec,
            });

            if (args.op === "insert") {
                const id = await writer.insert(args.table, args.doc ?? {});

                return { id, op: "insert" };
            }

            if (args.op === "delete") {
                await writer.delete(args.id ?? "");

                return { id: args.id ?? null, op: "delete" };
            }

            if (args.op === "replace") {
                await writer.replace(args.id ?? "", args.doc ?? {});

                return { id: args.id ?? null, op: "replace" };
            }

            await writer.patch(args.id ?? "", args.doc ?? {});

            return { id: args.id ?? null, op: "patch" };
        }

        // The base `ShardDO` cannot build a schema-aware writer, so its
        // `runShardExport`/`runShardImport` return `[]` and `{inserted:{}}`.
        // Those are success-shaped: an empty export is what a correct export of
        // an empty shard looks like, so a backup of a populated sharded schema
        // reported success and wrote nothing, and an import reported success and
        // dropped every row. Overriding both here is what makes the two admin
        // RPCs real for a `.shardBy()` table.
        //
        // NOTE: the admin export RPC is not paginated — `parseExportShardArgs`
        // takes `tables`/`batchSize` but no cursor, and the coordinator issues
        // one call per shard — so the rows are collected into a single response.
        // `batchSize` bounds the SQLite scan page, not the reply. A shard holding
        // more rows than fit in the DO's memory budget will therefore fail the
        // export rather than stream it. That is a loud failure where the bug this
        // replaces was a silent empty one, but a cursor on the RPC is what makes
        // this a complete backup path for large shards.
        protected override async runShardExport(args: RunShardExportArgs): Promise<ExportRow[]> {
            this.ensureMigrated();

            const env = (this.env ?? {}) as Record<string, unknown>;
            const scheduler = (config.scheduler?.(env) ?? schedulerStub) as SchedulerLike;
            const writer = createShardCtxDb({
                broadcast: (delta) => {
                    this.recordChangedTable(delta.table, delta.indexKeys);
                },
                cdc: config.cdc ?? false,
                scheduler,
                schema: schema as unknown as SchemaLike,
                sql: this.sql as SqlExec,
            });

            const rows: ExportRow[] = [];

            // `exportShardRows` walks in keyset batches so a large table does not
            // materialize at once inside the generator; the admin RPC's response
            // is a single array, so it is collected here rather than streamed.
            for await (const row of exportShardRows(writer, schema as unknown as SchemaLike, { batchSize: args.batchSize, tables: args.tables })) {
                rows.push(row);
            }

            return rows;
        }

        protected override async runShardImport(args: RunShardImportArgs): Promise<ImportShardResult> {
            this.ensureMigrated();

            const env = (this.env ?? {}) as Record<string, unknown>;
            const scheduler = (config.scheduler?.(env) ?? schedulerStub) as SchedulerLike;
            const writer = createShardCtxDb({
                broadcast: (delta) => {
                    this.recordChangedTable(delta.table, delta.indexKeys);
                },
                cdc: config.cdc ?? false,
                scheduler,
                schema: schema as unknown as SchemaLike,
                sql: this.sql as SqlExec,
            });

            // `importShardRows` inserts with `allowExplicitId`, so a source
            // database's `_id`s carry across verbatim and every foreign key
            // referencing them stays valid without a second remapping pass.
            return importShardRows(writer, schema as unknown as SchemaLike, { rows: args.rows, startLine: args.startLine });
        }

        protected override async deleteRowThroughWriter(table: string, id: string, headroom?: TransactionHeadroomTracker): Promise<void> {
            const definition = (schema as unknown as SchemaLike).tables[table];

            if (!definition) {
                throw new LunoraError("UNKNOWN_TABLE", `unknown table: ${table}`, { status: 404 });
            }

            // `.global()` tables live in D1, not this DO's SQLite — the same
            // guard `runShardWrite` applies to single-row edits.
            if (definition.shardMode?.kind === "global") {
                throw new LunoraError("GLOBAL_TABLE_NOT_EDITABLE", `table "${table}" is global; edit it through D1, not the shard`, { status: 400 });
            }

            this.ensureMigrated();

            const env = (this.env ?? {}) as Record<string, unknown>;
            const scheduler = (config.scheduler?.(env) ?? schedulerStub) as SchedulerLike;
            const writer = createShardCtxDb({
                broadcast: (delta) => {
                    this.recordChangedTable(delta.table, delta.indexKeys);
                },
                cdc: config.cdc ?? false,
                // `runShardBulkDelete` (a normal `/rpc` dispatch) calls this with no
                // explicit `headroom`, so it falls back to `this.transactionHeadroom()`
                // — the SAME per-dispatch meter every other write goes through, mirroring
                // `buildCtx`'s `options.headroom ?? this.transactionHeadroom()`. The TTL
                // sweep (an alarm work item, no dispatch in flight) passes its own
                // by-value tracker explicitly instead.
                headroom: headroom ?? this.transactionHeadroom(),
                scheduler,
                schema: schema as unknown as SchemaLike,
                sql: this.sql as SqlExec,
            });

            // Routes through the writer (not raw SQL) so FTS / aggregate / rank
            // shadow tables stay in sync and `onDelete` cascades fire — the
            // bounded loop lives in the base `runShardBulkDelete`.
            await writer.delete(id);
        }

        protected override async runShardRankBefore(args: RunShardRankBeforeArgs): Promise<{ before: number; total: number }> {
            this.ensureMigrated();

            const env = (this.env ?? {}) as Record<string, unknown>;
            const scheduler = (config.scheduler?.(env) ?? schedulerStub) as SchedulerLike;
            const writer = createShardCtxDb({
                broadcast: (delta) => {
                    this.recordChangedTable(delta.table, delta.indexKeys);
                },
                cdc: config.cdc ?? false,
                scheduler,
                schema: schema as unknown as SchemaLike,
                sql: this.sql as SqlExec,
            });

            // `rankBefore` is optional on `DatabaseWriterLike` (the D1 twin omits it),
            // but the shard writer from `createShardCtxDb` always defines it.
            if (!writer.rankBefore) {
                throw new LunoraError("NOT_IMPLEMENTED", "rankBefore is unavailable on the shard writer", { status: 500 });
            }

            return writer.rankBefore(args.table, args.index, {
                partitionKey: args.partitionKey,
                rowId: args.rowId,
                sortValues: args.sortValues,
            });
        }

        protected override async runShardRankPage(args: RunShardRankPageArgs): Promise<ShardRankPageResult> {
            this.ensureMigrated();

            const env = (this.env ?? {}) as Record<string, unknown>;
            const scheduler = (config.scheduler?.(env) ?? schedulerStub) as SchedulerLike;
            const writer = createShardCtxDb({
                broadcast: (delta) => {
                    this.recordChangedTable(delta.table, delta.indexKeys);
                },
                cdc: config.cdc ?? false,
                scheduler,
                schema: schema as unknown as SchemaLike,
                sql: this.sql as SqlExec,
            });

            // `rankPageRows` is optional on `DatabaseWriterLike` (the D1 twin omits it),
            // but the shard writer from `createShardCtxDb` always defines it. The sort
            // directions live in the schema's rankIndex, so the shard reads them itself;
            // `args.directions` is only the coordinator's comparator hint and isn't forwarded.
            if (!writer.rankPageRows) {
                throw new LunoraError("NOT_IMPLEMENTED", "rankPage is unavailable on the shard writer", { status: 500 });
            }

            return writer.rankPageRows(args.table, args.index, {
                after: args.after,
                cursor: args.cursor,
                partitionKey: args.partitionKey,
                take: args.take,
            });
        }

        protected override async runShardApplyCdc(args: RunShardApplyCdcArgs): Promise<{ applied: number }> {
            this.ensureMigrated();

            const env = (this.env ?? {}) as Record<string, unknown>;
            const scheduler = (config.scheduler?.(env) ?? schedulerStub) as SchedulerLike;
            const writer = createShardCtxDb({
                broadcast: (delta) => {
                    this.recordChangedTable(delta.table, delta.indexKeys);
                },
                cdc: config.cdc ?? false,
                scheduler,
                schema: schema as unknown as SchemaLike,
                sql: this.sql as SqlExec,
            });

            await applyCdcChanges(writer, args.changes);

            return { applied: args.changes.length };
        }

        protected override ensureMigrated(): void {
            if (this.migrated) {
                return;
            }

            runShardMigrations(this.sql as SqlExec, schema as unknown as SchemaLike, { cdc: config.cdc ?? false, schemaSnapshot: LUNORA_SCHEMA_SNAPSHOT });
            this.migrated = true;
        }

        private buildCtx(options: { functionPath?: string; headroom?: TransactionHeadroomTracker; identity?: { identity?: Record<string, unknown>; userId?: string }; onRead?: (table: string, idOrScan?: string) => void; onReadRange?: (range: KeyRange) => void } = {}): unknown {
            const env = (this.env ?? {}) as Record<string, unknown>;
            // When the caller threads an explicit identity (subscription seed /
            // refresh — both run in deferred/interleaved contexts), use it by
            // value and NEVER read the shared per-request identity field, which a
            // concurrent RPC may have re-set. Otherwise (the synchronous RPC
            // dispatch path) fall back to the per-request fields as before.
            const userId = options.identity ? options.identity.userId : this.getCurrentUserId();
            const identity = options.identity ? options.identity.identity : this.getCurrentIdentity();

            const aiBinding = config.ai?.(env) ?? (env as Record<string, unknown>).AI;
            // Correlate AI-Gateway-routed calls with the Lunora trace: thread the
            // function path + trace id into createAi, which folds them into the
            // gateway's native `metadata` only when a gateway is configured (absent
            // otherwise). Mirror the tracer's anchor guard — a deferred subscription
            // re-run must not borrow a concurrent dispatch's trace, so read
            // `getCurrentTrace()` only on the synchronous (non-threaded-identity) path.
            const aiTrace = options.identity ? undefined : this.getCurrentTrace();
            const ai: LunoraAi = aiBinding
                ? createAi({ binding: aiBinding as AiBindingLike, env: env as Record<string, unknown>, metadata: { functionPath: options.functionPath, traceId: aiTrace?.traceId } })
                : aiStub;

            const envConfig = lunoraEnvContract.env(env);

            const secrets = createSecrets(env);

            const scheduler = (config.scheduler?.(env) ?? schedulerStub) as SchedulerLike;
            // Build the storage adapter once and share it between `ctx.storage`
            // and `ctx.db.system._storage` so both read the same R2 binding. The
            // `storageStub` fallback satisfies SystemReaderStorageLike structurally
            // (its `list`/`getMetadata` throw the "no storage configured" error).
            const storage = asBucketStorage(config.storage?.(env) ?? storageStub) as unknown as SystemReaderStorageLike;
            // `ctx.log`: the DO base builds the attributed logger (structured
            // fields + `.with(...)` child + trace correlation) and routes each call
            // to the optional `observability` sink. It also buffers the line (studio
            // Logs panel) and emits a structured console event the dev-server formats.
            //
            // Resolved BEFORE `ctx.db` below, because the database is wrapped in
            // auto-instrumentation that needs the sink, the trace anchor, and the
            // dispatch's wide-event handle.
            const observability = config.observability?.(env);
            const logFunctionPath = options.functionPath ?? "";
            const log = this.makeLogger(logFunctionPath, observability);
            const traceAnchor = this.resolveDispatchAnchor(Boolean(options.identity));

            // `ctx.span`: the handle onto the DISPATCH's own span — the wide-event
            // surface. Attributes attached here accumulate for the whole request
            // and are folded into the one span it already emits, instead of
            // becoming N separate log lines. Shares `traceAnchor` with `ctx.trace`
            // so both write to the same trace.
            const span = this.makeDispatchSpan(traceAnchor, observability);

            const globalDb: DatabaseWriterLike = config.d1?.(env, { identity, userId }) ?? globalDbStub;
            // `ctx.db`, wrapped in automatic instrumentation: by default this
            // adds aggregate counters (call count, total time, per-operation
            // breakdown) to the wide event rather than a span per call, so a
            // handler making hundreds of queries stays readable. See
            // `instrumentDatabase` for the `"spans"` / `"off"` levels.
            const db: DatabaseWriterLike = this.instrumentDb(createShardCtxDb({
                auth: { identity: identity ?? null, userId: userId ?? null },
                broadcast: (delta) => {
                    this.recordChangedTable(delta.table, delta.indexKeys);
                },
                cdc: config.cdc ?? false,
                enforceRls: true,
                headroom: options.headroom ?? this.transactionHeadroom(),
                onIndexUse: this.getCtxDbIndexUseHook(),
                onRead: options.onRead ?? this.getCtxDbReadHook(),
                onReadRange: options.onReadRange,
                scheduler,
                schema: schema as unknown as SchemaLike,
                sql: this.sql as SqlExec,
                storage,
                globalDb,
            }), logFunctionPath, traceAnchor, observability);

            const facade = db as unknown as Record<string, ReturnType<typeof bindTableFacade>>;
            facade["cells"] = bindTableFacade(db, "cells");
            facade["organizations"] = bindTableFacade(db, "organizations");
            facade["members"] = bindTableFacade(db, "members");
            facade["projects"] = bindTableFacade(db, "projects");
            facade["deployments"] = bindTableFacade(db, "deployments");
            facade["aliasOwnership"] = bindTableFacade(db, "aliasOwnership");
            facade["metricPoints"] = bindTableFacade(db, "metricPoints");
            facade["deployKeys"] = bindTableFacade(db, "deployKeys");
            facade["overageDebits"] = bindTableFacade(db, "overageDebits");
            facade["tenantLogs"] = bindTableFacade(db, "tenantLogs");
            facade["observations"] = bindTableFacade(db, "observations");
            facade["githubInstallations"] = bindTableFacade(db, "githubInstallations");
            facade["builds"] = bindTableFacade(db, "builds");
            facade["buildLogs"] = bindTableFacade(db, "buildLogs");
            facade["domains"] = bindTableFacade(db, "domains");
            facade["auditLog"] = bindTableFacade(db, "auditLog");
            facade["invitations"] = bindTableFacade(db, "invitations");
            facade["platformUsage"] = bindTableFacade(db, "platformUsage");
            facade["issues"] = bindTableFacade(db, "issues");
            facade["incidents"] = bindTableFacade(db, "incidents");
            facade["alertRules"] = bindTableFacade(db, "alertRules");
            facade["alertRuleState"] = bindTableFacade(db, "alertRuleState");
            facade["alerts"] = bindTableFacade(db, "alerts");
            facade["uptimeChecks"] = bindTableFacade(db, "uptimeChecks");
            facade["uptimeState"] = bindTableFacade(db, "uptimeState");
            facade["secrets"] = bindTableFacade(db, "secrets");
            facade["cloudflareBilling"] = bindTableFacade(db, "cloudflareBilling");
            facade["dashboards"] = bindTableFacade(db, "dashboards");
            facade["customers"] = bindTableFacade(db, "customers");
            facade["events"] = bindTableFacade(db, "events");
            facade["paymentSessions"] = bindTableFacade(db, "paymentSessions");
            facade["subscriptions"] = bindTableFacade(db, "subscriptions");
            facade["usageEvents"] = bindTableFacade(db, "usageEvents");
            facade["rateLimits"] = bindTableFacade(db, "rateLimits");

            const payments: LunoraPayment = config.payment
                ? paymentsFromContext({ auth: { userId: userId ?? null }, db: db as unknown as LunoraPaymentDbLike }, config.payment(env))
                : paymentStub;


            // `ctx.trace` / `ctx.metrics`: spans and measurements to the same sink.
            // The trace anchor is threaded explicitly for the same reason `identity`
            // is — a deferred caller (a subscription re-run) must not inherit the
            // writing mutation's trace from the shared per-request field.
            const trace = this.makeTracer(logFunctionPath, observability, traceAnchor);
            const metrics = this.makeMetrics(logFunctionPath, observability);

            // `ctx.now`: the wall-clock instant (epoch ms) this function began,
            // captured ONCE so the whole handler body sees a single stable value.
            // Query/mutation handlers must be deterministic (they may be re-run on
            // OCC retry / subscription re-eval), so they must read time through
            // `ctx.now` instead of `Date.now()` — the `nondeterministic_query_mutation`
            // advisor flags the latter. Actions may still use ambient `Date.now()`.
            const now = Date.now();

            const ctx: Record<string, unknown> = {
                auth: {
                    getIdentity: async () => identity ?? null,
                    userId: userId ?? null,
                },
                db,
                // Instrumented `fetch`: a CLIENT span per outbound call plus W3C
                // `traceparent` propagation, so time spent in a downstream service
                // is visible and its spans join this trace. Degrades to the bare
                // global when no sink is configured.
                fetch: this.makeFetch(logFunctionPath, traceAnchor, observability),
                ip: this.getCurrentIp(),
                log,
                metrics,
                now,
                orm: bindOrm(facade),
                scheduler,
                span,
                storage,
                trace,
                ai,
                env: envConfig,
                secrets,
                payments,
            };

            ctx.runAction = (reference: FunctionReference, fnArgs: Record<string, unknown>) => dispatchRun("action", reference.__lunoraRef, fnArgs, ctx);
            ctx.runMutation = (reference: FunctionReference, fnArgs: Record<string, unknown>) => dispatchRun("mutation", reference.__lunoraRef, fnArgs, ctx);
            ctx.runQuery = (reference: FunctionReference, fnArgs: Record<string, unknown>) => dispatchRun("query", reference.__lunoraRef, fnArgs, ctx);

            return ctx;
        }
    };
